$('fight').onclick=()=>{if(!formation.some(f=>f.team==='blue')||!formation.some(f=>f.team==='red')){toast('Posicione pelo menos um lutador em cada time.');return;}acc=0;battle=new Battle(formation,battleEvent);$('fight').hidden=true;$('reset').hidden=false;$('pause').disabled=false;document.body.classList.add('battling');beep(650,.2);updateUI();};$('reset').onclick=stop;$('again').onclick=()=>{$('resultDialog').close();stop();};$('next').onclick=()=>{$('resultDialog').close();stop();level++;loadChallenge();};$('pause').onclick=()=>{paused=!paused;$('pause').textContent=paused?'▶':'Ⅱ';updateUI();};$('speed').onclick=()=>{speed=speed===1?2:speed===2?.5:1;$('speed').textContent=speed+'×';};$('sound').onclick=()=>{sound=!sound;$('sound').style.color=sound?'#d7ff62':'';$('sound').setAttribute('aria-label',sound?'Desativar som':'Ativar som');beep(600);toast(sound?'Som ativado':'Som desativado');};$('teamBlue').onclick=()=>{team='blue';updateUI();};$('teamRed').onclick=()=>{team='red';updateUI();};$('erase').onclick=()=>{erase=!erase;orbit=false;updateUI();};$('clear').onclick=()=>{if(battle)return;formation=formation.filter(f=>f.team!==team);rebuild();};$('demo').onclick=demo;$('sandbox').onclick=()=>setMode('sandbox');$('campaign').onclick=()=>setMode('campaign');$('camera').onclick=()=>{orbit=!orbit;updateUI();};$('zoomIn').onclick=()=>{distance=Math.max(15,distance-3);cameraUpdate();};$('zoomOut').onclick=()=>{distance=Math.min(48,distance+3);cameraUpdate();};$('quality').onclick=()=>{quality=!quality;renderer.setPixelRatio(quality?Math.min(devicePixelRatio,2):Math.min(devicePixelRatio,1.25));$('qualityText').textContent=quality?'ALTO':'LEVE';};$('help').onclick=()=>$('helpDialog').showModal();document.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>$(b.dataset.close).close());
