canvas.addEventListener('pointerup',e=>{touches.delete(e.pointerId);if(moved||battle||orbit||!start){if(!touches.size)start=null;return;}start=null;pointer.set(e.clientX/innerWidth*2-1,1-e.clientY/innerHeight*2);ray.setFromCamera(pointer,camera);if(!ray.ray.intersectPlane(plane,hit))return;if(erase){let idx=-1,dist=1;formation.forEach((f,i)=>{const d=Math.hypot(f.x-hit.x,f.z-hit.z);if(d<dist&&(mode!=='campaign'||f.team==='blue')){dist=d;idx=i;}});if(idx>=0){formation.splice(idx,1);rebuild();}return;}if(Math.abs(hit.x)>11||Math.abs(hit.z)>7){toast('Toque dentro da arena.');return;}if((team==='blue'&&hit.x>-.5)||(team==='red'&&hit.x<.5)){toast(`Posicione no lado ${team==='blue'?'azul (esquerda)':'vermelho (direita)'}.`);return;}if(add(selected,team,hit.x,hit.z)){rebuild();beep(350);}});
canvas.addEventListener('pointercancel',e=>{touches.delete(e.pointerId);start=null;moved=true;});canvas.addEventListener('wheel',e=>{e.preventDefault();distance=Math.max(15,Math.min(48,distance+e.deltaY*.02));cameraUpdate();},{passive:false});canvas.addEventListener('contextmenu',e=>e.preventDefault());
function animate(t){requestAnimationFrame(animate);const dt=Math.min((t-last)/1000||0,.05);last=t;elapsed+=dt;if(battle&&!paused&&!battle.finished){acc+=dt*speed;let steps=0;while(acc>=1/60&&steps++<8){battle.step(1/60);acc-=1/60;}if(steps>=8)acc=0;}if(battle){battle.units.forEach((u,i)=>{const v=views[i],d=v.userData;v.position.set(u.x,0,u.z);if(u.angle!==undefined)v.rotation.y=u.angle;if(!u.hp){d.body.rotation.z=Math.min(Math.PI/2,u.dead*5);d.body.position.y=-Math.min(.15,u.dead*.2);v.visible=u.dead<6;d.bar.visible=d.barBack.visible=false;return;}d.body.position.y=Math.sin(elapsed*9+i)*.025;d.body.rotation.x=u.attack>0?-.16:0;d.legs.forEach((l,j)=>l.rotation.x=Math.sin(elapsed*10+i+j*Math.PI)*.38);d.arms.forEach((a,j)=>a.rotation.x=u.attack>0?-1.5:Math.sin(elapsed*10+i+j*Math.PI)*.3);d.bar.scale.x=.68*u.hp/u.maxHp;d.bar.position.x=-(.68-d.bar.scale.x)/2;d.ring.material.color.set(u.hit>0?0xffffff:u.team==='blue'?0x68d2ff:0xff7976);});}else views.forEach((v,i)=>{v.userData.body.position.y=Math.sin(elapsed*2+i)*.018;});for(let i=effects.length-1;i>=0;i--){const e=effects[i];if(!paused)e.ttl-=dt*speed;if(e.ttl<=0){scene.remove(e.mesh);if(e.kind==='clone'){e.mesh.userData.shadow.material.dispose();e.mesh.userData.ring.material.dispose();}effects.splice(i,1);continue;}if(e.kind==='particle'){e.mesh.position.x+=e.vx*dt;e.mesh.position.y+=e.vy*dt;e.mesh.position.z+=e.vz*dt;e.vy-=12*dt;e.mesh.scale.setScalar(.12*e.ttl/e.max);}else if(e.kind==='beam')e.mesh.scale.x*=.97;}if(Math.floor(elapsed*5)!==Math.floor((elapsed-dt)*5))updateUI();renderer.render(scene,camera);}try{formation=validFormation(JSON.parse(localStorage.getItem('pixelChaos.formation.v1')||'[]'));}catch{}if(!formation.length)demo();else rebuild();requestAnimationFrame(animate);
window.__PIXEL_CHAOS__={get formation(){return formation;},get battle(){return battle;},get mode(){return mode;},renderer};
